import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const u=JSON.parse('{"title":"预约医院就诊时间","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/dialogues/01-hospital-appointment.md","filePath":"zh/more/maltese/practice/dialogues/01-hospital-appointment.md"}'),e={name:"zh/more/maltese/practice/dialogues/01-hospital-appointment.md"},o=r('<h1 id="预约医院就诊时间" tabindex="-1">预约医院就诊时间 <a class="header-anchor" href="#预约医院就诊时间" aria-label="Permalink to &quot;预约医院就诊时间&quot;">​</a></h1><p><strong>场景：</strong> David 打电话到健康中心，向接待员 Maria 预约医生并确认时间和证件。</p><h2 id="完整对话" tabindex="-1">完整对话 <a class="header-anchor" href="#完整对话" aria-label="Permalink to &quot;完整对话&quot;">​</a></h2><p><strong>Maria：</strong> Bonġu, Ċentru tas-Saħħa. Kif nista&#39; ngħinek?</p><p><strong>David：</strong> Bonġu. Nixtieq nagħmel appuntament mat-tabib, jekk jogħġbok.</p><p><strong>Maria：</strong> Għandek preferenza għal xi ġurnata?</p><p><strong>David：</strong> Jekk jista&#39; jkun, għada filgħodu.</p><p><strong>Maria：</strong> Għandna ħin fl-għaxra u nofs. Tajjeb għalik?</p><p><strong>David：</strong> Iva, tajjeb ħafna. Għandi bżonn inġib xi dokumenti?</p><p><strong>Maria：</strong> Ġib il-karta tal-identità u l-karta tas-saħħa.</p><p><strong>David：</strong> Grazzi. Narak għada.</p><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><h3 id="_1-maria-接待员" tabindex="-1">1. Maria（接待员） <a class="header-anchor" href="#_1-maria-接待员" aria-label="Permalink to &quot;1. Maria（接待员）&quot;">​</a></h3><p><strong>Malti:</strong> Bonġu, Ċentru tas-Saħħa. Kif nista&#39; ngħinek?</p><p><strong>整句：</strong> 早上好，这里是健康中心。我可以怎样帮您？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Bonġu</td><td>你好；早上好</td><td>常见问候语</td></tr><tr><td>Ċentru</td><td>中心</td><td>阳性名词</td></tr><tr><td>tas-Saħħa</td><td>健康的</td><td><code>ta&#39; + is-saħħa</code> 的缩合形式，意为“健康中心的”</td></tr><tr><td>Kif</td><td>怎样；如何</td><td>疑问词</td></tr><tr><td>nista&#39;</td><td>我可以</td><td><code>n-</code> 第一人称标记；<code>jista&#39;</code> 表示“能够”</td></tr><tr><td>ngħinek</td><td>帮助您/你</td><td><code>ngħin</code>“我帮助” + <code>-ek</code>“你”</td></tr></tbody></table><h3 id="_2-david-病人" tabindex="-1">2. David（病人） <a class="header-anchor" href="#_2-david-病人" aria-label="Permalink to &quot;2. David（病人）&quot;">​</a></h3><p><strong>Malti:</strong> Bonġu. Nixtieq nagħmel appuntament mat-tabib, jekk jogħġbok.</p><p><strong>整句：</strong> 早上好。我想预约看医生，麻烦您。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Bonġu</td><td>你好；早上好</td><td>问候语</td></tr><tr><td>Nixtieq</td><td>我想要</td><td>礼貌表达愿望</td></tr><tr><td>nagħmel</td><td>我做；我安排</td><td><code>nagħmel appuntament</code> 表示“预约”</td></tr><tr><td>appuntament</td><td>预约；约会</td><td>阳性名词，借词</td></tr><tr><td>mat-tabib</td><td>和/与医生；看医生</td><td><code>ma&#39;</code>“和” + 定冠词 <code>it-</code>，发生拼写缩合</td></tr><tr><td>jekk</td><td>如果</td><td>常与 <code>jogħġbok</code> 构成礼貌用语</td></tr><tr><td>jogħġbok</td><td>请；使您高兴</td><td><code>jekk jogħġbok</code> 整体相当于“请/麻烦您”</td></tr></tbody></table><h3 id="_3-maria-接待员" tabindex="-1">3. Maria（接待员） <a class="header-anchor" href="#_3-maria-接待员" aria-label="Permalink to &quot;3. Maria（接待员）&quot;">​</a></h3><p><strong>Malti:</strong> Għandek preferenza għal xi ġurnata?</p><p><strong>整句：</strong> 您比较希望哪一天？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għandek</td><td>你有；您有</td><td><code>għand</code> 的第二人称单数形式</td></tr><tr><td>preferenza</td><td>偏好；选择</td><td>阴性名词</td></tr><tr><td>għal</td><td>对于；关于</td><td>介词</td></tr><tr><td>xi</td><td>某个；任何</td><td>这里用于询问“哪一天”</td></tr><tr><td>ġurnata</td><td>一天；日子</td><td>阴性名词</td></tr></tbody></table><h3 id="_4-david-病人" tabindex="-1">4. David（病人） <a class="header-anchor" href="#_4-david-病人" aria-label="Permalink to &quot;4. David（病人）&quot;">​</a></h3><p><strong>Malti:</strong> Jekk jista&#39; jkun, għada filgħodu.</p><p><strong>整句：</strong> 如果可以的话，明天早上。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jekk</td><td>如果</td><td>连词</td></tr><tr><td>jista&#39;</td><td>可以；可能</td><td>第三人称阳性单数形式</td></tr><tr><td>jkun</td><td>是；成为</td><td><code>ikun</code> 的虚拟/从属形式，见于固定表达 <code>jekk jista&#39; jkun</code></td></tr><tr><td>għada</td><td>明天</td><td>时间副词</td></tr><tr><td>filgħodu</td><td>在早上</td><td>时间表达；源自“早晨”一类形式</td></tr></tbody></table><h3 id="_5-maria-接待员" tabindex="-1">5. Maria（接待员） <a class="header-anchor" href="#_5-maria-接待员" aria-label="Permalink to &quot;5. Maria（接待员）&quot;">​</a></h3><p><strong>Malti:</strong> Għandna ħin fl-għaxra u nofs. Tajjeb għalik?</p><p><strong>整句：</strong> 我们十点半有空。这个时间对您合适吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għandna</td><td>我们有</td><td><code>għand</code> 的第一人称复数形式</td></tr><tr><td>ħin</td><td>时间；空闲时间</td><td>阳性名词</td></tr><tr><td>fl-għaxra</td><td>在十点</td><td><code>f&#39;</code>“在” + <code>l-għaxra</code>“十点”的缩合形式</td></tr><tr><td>u</td><td>和；过</td><td>此处连接整点与“半”</td></tr><tr><td>nofs</td><td>一半；半</td><td>时间表达中表示半点</td></tr><tr><td>Tajjeb</td><td>好；合适</td><td>阳性形式；此处指时间合适</td></tr><tr><td>għalik</td><td>对你；对您</td><td><code>għal</code>“对” + <code>-ik</code>“你”</td></tr></tbody></table><h3 id="_6-david-病人" tabindex="-1">6. David（病人） <a class="header-anchor" href="#_6-david-病人" aria-label="Permalink to &quot;6. David（病人）&quot;">​</a></h3><p><strong>Malti:</strong> Iva, tajjeb ħafna. Għandi bżonn inġib xi dokumenti?</p><p><strong>整句：</strong> 是的，非常合适。我需要带什么文件吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Iva</td><td>是；对</td><td>肯定回答</td></tr><tr><td>tajjeb</td><td>好；合适</td><td>阳性形式</td></tr><tr><td>ħafna</td><td>很；非常；许多</td><td>此处修饰 <code>tajjeb</code>，表示“非常”</td></tr><tr><td>Għandi</td><td>我有</td><td><code>għand</code> 的第一人称单数形式</td></tr><tr><td>bżonn</td><td>需要</td><td><code>għandi bżonn</code> 整体表示“我需要”</td></tr><tr><td>inġib</td><td>我带来；我拿来</td><td>第一人称单数形式</td></tr><tr><td>xi</td><td>一些；什么</td><td>疑问句中可表示“什么”</td></tr><tr><td>dokumenti</td><td>文件；证件</td><td><code>dokument</code> 的复数</td></tr></tbody></table><h3 id="_7-maria-接待员" tabindex="-1">7. Maria（接待员） <a class="header-anchor" href="#_7-maria-接待员" aria-label="Permalink to &quot;7. Maria（接待员）&quot;">​</a></h3><p><strong>Malti:</strong> Ġib il-karta tal-identità u l-karta tas-saħħa.</p><p><strong>整句：</strong> 请带上身份证和健康卡。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Ġib</td><td>带来；拿来</td><td>对一人的命令式</td></tr><tr><td>il-karta</td><td>卡；纸张</td><td><code>il-</code> 定冠词 + <code>karta</code></td></tr><tr><td>tal-identità</td><td>身份的</td><td><code>ta&#39; + l-identità</code> 的缩合形式</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>il-karta</td><td>卡</td><td>阴性名词，带定冠词</td></tr><tr><td>tas-saħħa</td><td>健康的</td><td><code>ta&#39; + is-saħħa</code> 的缩合形式</td></tr></tbody></table><h3 id="_8-david-病人" tabindex="-1">8. David（病人） <a class="header-anchor" href="#_8-david-病人" aria-label="Permalink to &quot;8. David（病人）&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi. Narak għada.</p><p><strong>整句：</strong> 谢谢。明天见。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Grazzi</td><td>谢谢</td><td>常用礼貌用语</td></tr><tr><td>Narak</td><td>我见到你；再见</td><td><code>nara</code>“我看见” + <code>-k</code>“你”</td></tr><tr><td>għada</td><td>明天</td><td>时间副词</td></tr></tbody></table><h2 id="可替换表达" tabindex="-1">可替换表达 <a class="header-anchor" href="#可替换表达" aria-label="Permalink to &quot;可替换表达&quot;">​</a></h2><ul><li><code>filgħodu</code>：早上；<code>wara nofsinhar</code>：下午；<code>filgħaxija</code>：晚上。</li><li><code>Għandi appuntament.</code>：我有预约。</li><li><code>Nista&#39; nbiddel il-ħin?</code>：我可以改时间吗？</li></ul>',46),i=[o];function n(h,l,s,c,g,p){return d(),a("div",null,i)}const k=t(e,[["render",n]]);export{u as __pageData,k as default};
